const themes=[['01','自然接触与情绪健康','Nature & emotional health','通过混合方法研究，理解自然接触带来的情绪体验，探索其改善抑郁症状的机制与干预应用。','Using mixed methods to understand emotional experiences of nature contact and its mechanisms and applications for depressive symptoms.'],['02','正念与心理干预','Mindfulness & psychological interventions','关注正念、积极心理干预与情绪调节，探索日常生活中可及的心理健康支持。','Exploring mindfulness, positive psychological interventions and emotion regulation as accessible approaches to mental health support.'],['03','情绪的心理生理机制','Psychophysiology of emotion','结合心理学与生物医学工程，研究情绪诱发、外周生理信号及情绪识别。','Connecting psychology and biomedical engineering to study emotion elicitation, peripheral physiological signals and emotion recognition.']];
const themeHtml=()=>themes.map(t=>`<article class="theme"><span>${t[0]}</span><h3>${L(t[1],t[2])}</h3><p>${L(t[3],t[4])}</p></article>`).join('');
const intro=L('我关注人与自然的关系，以及日常经验如何影响情绪与心理健康。研究结合定量、定性与心理生理方法，并与心理干预实践相联结。','I study relationships between people and nature, and how everyday experiences shape emotion and mental health. My work brings together quantitative, qualitative and psychophysiological methods, connecting research with psychological intervention practice.');
const edu=()=>item(L('浙江大学 · 临床心理学博士','Zhejiang University · Doctoral degree, Clinical Psychology'),L('心理与行为科学系，教育学博士。导师：陈树林教授。博士论文聚焦自然接触对抑郁症状的机制与干预。','Department of Psychology and Behavioral Sciences; doctoral degree in Education, specializing in Clinical Psychology. Supervisor: Prof. Shulin Chen. Dissertation on mechanisms and interventions linking nature contact and depressive symptoms.'),'2021.09 — 2026.06')+item(L('华盛顿大学 · 国际联合培养','University of Washington · Visiting doctoral training'),L('心理系，导师：Peter H. Kahn 教授。国家留学基金委资助，研究户外行走与抑郁症状。','Department of Psychology. Supervisor: Prof. Peter H. Kahn. China Scholarship Council (CSC)-funded training on outdoor walking and depressive symptoms.'),'2025.01 — 2026.01')+item(L('浙江大学 · 心理学学士','Zhejiang University · Bachelor of Science in Psychology'),L('心理与行为科学系，理学学士。','Department of Psychology and Behavioral Sciences.'),'2017.09 — 2021.06');
let body='';
if(page==='home') body=`<section class="hero"><img src="assets/hero.webp" alt="${L('晨光下的森林与宁静水面艺术画','Fine-art woodland and still water in morning light')}" fetchpriority="high"><div class="hero-content"><div class="eyebrow">NATURE · EMOTION · WELL-BEING</div><h1>${L('王宣懿','Xuanyi Wang')}</h1><div class="roman">${L('Xuanyi Wang','王宣懿')}</div><p class="role">${L('温州医科大学精神医学学院 · 讲师','Lecturer · School of Mental Health, Wenzhou Medical University')}</p><p class="hero-line">${L('在自然中，理解情绪。<br>在研究与实践间，关照人的成长。','Understanding emotion through nature.<br>Connecting research, practice and human growth.')}</p><a class="button" href="research.html${en?'?lang=en':''}">${L('探索我的研究','Explore my research')} <span>↗</span></a></div><div class="hero-note">${L('自然 · 情绪 · 心理健康','Nature · Emotion · Well-being')}</div></section>${section('01 / ABOUT','关于我','About me',`<div class="intro">${intro}</div><p>${L('浙江大学临床心理学博士，曾赴美国华盛顿大学心理系国际联合培养。现为温州医科大学精神医学学院讲师，从事研究、教学与心理咨询相关实践。','I received my doctoral training in clinical psychology at Zhejiang University, with international joint doctoral training at the University of Washington. I am a lecturer at the School of Mental Health, Wenzhou Medical University, working across research, teaching and counseling practice.')}</p>`)}${section('02 / RESEARCH','研究的三个切面','Three strands of research',`<div class="themes">${themeHtml()}</div>`)}${section('03 / SELECTED WORK','代表性研究','Selected publications','<div id="publications" data-selected="true"></div><a class="text-link" href="research.html'+(en?'?lang=en':'')+'">'+L('查看全部研究成果','View all publications')+' ↗</a>')}`;
if(page==='research') body=`<header class="page-head">${heading('RESEARCH & PUBLICATIONS','从自然经验，走向心理健康','From nature experience<br>to mental health')}<p>${intro}</p></header>${section('01 / FOCUS','研究方向','Research interests',`<div class="themes">${themeHtml()}</div>`)}${section('02 / PROJECTS','研究项目','Research projects',item(L('自然行走与城市行走','Nature walking and urban walking'),L('抑郁症状干预的随机对照研究。国家建设高水平大学公派研究生项目，项目负责人；导师：Peter H. Kahn、陈树林。','A randomized controlled study on depressive symptoms. Doctoral research funded by the China Scholarship Council (CSC); project lead, supervised by Peter H. Kahn and Shulin Chen.'))+item(L('自然与情绪健康','Nature and emotional health'),L('博士论文项目：结合定性与定量方法，探索自然改善情绪健康的作用与机制，项目负责人。','Doctoral dissertation project combining qualitative and quantitative methods to investigate the effects and mechanisms of nature on emotional health; project lead.'))+item(L('悲伤情绪与心理生理研究','Sadness and psychophysiology'),L('心理学与生物医学工程联合项目，核心成员，2023—2025。另参与情绪诱发与外周生理信号情绪识别研究（2022—2024）。','Core member of an interdisciplinary psychology and biomedical engineering project, 2023–2025. Also contributed to emotion elicitation and recognition using peripheral physiological signals, 2022–2024.'))+item(L('心理健康求助与咨询师胜任力','Help-seeking and counselor competencies'),L('参与心理健康求助行为研究（2021—2025）；指导本科生开展心理咨询师胜任力研究（2023—2025）。','Collaborated on mental health help-seeking research (2021–2025) and guided undergraduate research on counselor competencies (2023–2025).')))}${section('03 / PUBLICATIONS','论文与会议论文','Journal & conference publications','<p class="muted">'+L('按年份倒序排列；作者顺序与论文题名保留简历原文。* 表示简历标注的通讯作者。','Listed by year. Author order and titles follow the supplied curriculum vitae. * denotes corresponding authors as marked in the CV.')+'</p><div id="publications"></div>')}${section('04 / EDUCATION','教育经历','Education',edu())}`;
if(page==='teaching') body=`<header class="page-head">${heading('TEACHING & EXCHANGE','让知识，连接真实生活','Bringing knowledge<br>into everyday life')}<p>${L('教学、团体学习与跨学科交流，是研究走向实践的重要路径。','Teaching, group learning and interdisciplinary exchange connect research with practice.')}</p></header>${section('01 / TEACHING','教学经历','Teaching experience',para('既往参与研究生、本科生、继续教育及中学课程。简历记录包含主讲、参与授课与助教经历；下列课程不统一标注为独立主讲。','Prior experience spans graduate, undergraduate, continuing education and secondary-school courses. Roles include lead teaching, contributing teaching and teaching assistance; the courses below are not all independently taught.')+item(L('研究生与本科课程','Graduate & undergraduate courses'),L('浙江大学：压力管理能力建设、心理评估与诊断、教育心理学、景观规划设计、幸福心理学、社区心理学、社会心理学。中国美术学院：自然疗愈心理团辅。','Zhejiang University: stress management, psychological assessment and diagnosis, educational psychology, landscape planning and design, psychology of happiness, community psychology and social psychology. China Academy of Art: nature-based psychological group work.'))+item(L('继续教育与中学课程','Continuing & secondary education'),L('浙江大学：助人技术、积极心理学、基本咨询技术。杭州第二中学：非暴力沟通；杭州崇贤中学：自我成长团辅。','Zhejiang University: helping skills, positive psychology and basic counseling skills. Hangzhou No. 2 High School: nonviolent communication; Chongxian Middle School: personal growth group work.')))}${section('02 / DEVELOPMENT','教学改革项目','Teaching development',item(L('临床心理学博士课程实践改革','Clinical psychology doctoral curriculum reform'),L('协助申请与落地“跨学科协同下的临床心理学博士以心理诊断为核心的课程实践改革”，获浙江省高等教育“十四五”研究生教学改革项目立项。','Assisted with the application and implementation of a Zhejiang provincial graduate teaching reform project on interdisciplinary doctoral clinical psychology training centered on psychological diagnosis.'))+item(L('研究生压力管理能力建设','Graduate student stress management'),L('协助申请与落地浙江大学2024研究生教育教学成果培育项目。','Assisted with the application and implementation of a 2024 Zhejiang University graduate education development project.')))}${section('03 / EXCHANGE','代表性学术交流','Selected academic presentations',item('World Forum on Forest Therapy',L('自然相关积极情绪的反思性主题分析，口头报告。','Positive emotions connected with nature: reflexive thematic analysis. Oral presentation.'),'2024.10.28 — 10.30 · Daejeon')+item('Anxiety & Depression Conference',L('抑郁与非抑郁青年中华尔兹音乐对悲伤的心理生理作用，海报展示。','Psychophysiological effects of waltz music on sadness in youth with and without depressive symptoms. Poster.'),'2024.04.11 — 04.14 · Boston')+item('Singapore–China Forum on Healthy Aging and Urban Sustainability',L('自然接触对情绪健康的益处，口头报告。','Benefits of nature exposure for emotional health. Oral presentation.'),'2023.11.07 — 11.09 · Singapore')+item(L('浙江省休闲学年会','Zhejiang Leisure Studies Annual Conference'),L('数智化背景下基于室内的自然休闲方案设计及其价值阐释，口头报告；优秀学术论文学生组一等奖。','Indoor nature-based leisure design in a digital context. Oral presentation; first prize in the student academic paper category.'),'2025.10.17 — 10.18 · Shaoxing'))}${section('04 / BOOKS','书籍与知识传播','Books',item(L('心理调节之道：从了解到疗愈','Pathways of Psychological Adjustment'),L('陈树林、王宣懿编著。负责统编统修，撰写第十至十二章。浙江教育出版社。','Coauthored with Shulin Chen; coordinated editing and wrote Chapters 10–12. Zhejiang Education Publishing House.'),'2025.05 · ISBN 9787572298394')+item(L('压力管理：轻松愉悦生活之道','Stress Management'),L('陈树林主编。参编作者，撰写第二章“压力的应对与管理”。浙江大学出版社。','Edited by Shulin Chen. Contributing author of Chapter 2 on coping with and managing stress. Zhejiang University Press.'),'2023.11 · ISBN 9787308242998'))}`;
if(page==='counseling') body=`<header class="page-head counseling-head">${heading('COUNSELING & PRACTICE','在理解中，寻找成长的空间','Space for understanding.<br>Room for growth.')}<p>${L('以人本主义的理解为基础，结合认知行为、积极心理学与自然相关实践，关注情绪困扰与个人成长。','Grounded in a person-centered understanding, my practice draws on cognitive behavioral approaches, positive psychology and nature-related practices, with a focus on emotional difficulties and personal growth.')}</p></header><figure class="counsel-art"><img src="assets/counseling.webp" alt="${L('柔和晨光照亮林间小径的艺术画','A fine-art woodland path in soft morning light')}"></figure>${section('01 / APPROACH','咨询取向与设置','Approach & format',`<div class="setting-grid">${item(L('工作人群与议题','People & concerns'),L('成年人与青少年；情绪困扰与个人成长。服务范围以咨询前的具体沟通与评估为准。','Adults and adolescents; emotional difficulties and personal growth. Suitability is discussed and assessed before counseling.'))}${item(L('形式与时间','Format & frequency'),L('视频或线下面询；个体咨询每次50分钟，通常每周1—2次，具体安排通过邮件沟通。','Video or in-person individual sessions, 50 minutes each, typically once or twice weekly. Arrangements are discussed by email.'))}</div>`)}${section('02 / EXPERIENCE','实践经历','Practice experience',item(L('高校心理支持与团体辅导','University support & group work'),L('曾于中国美术学院担任兼职心理老师；参与浙江大学心理帮扶团校园实践；设计并带领自然疗愈、自然正念、人际沟通、时间管理及行为活化等主题团辅。','Previously a part-time psychology teacher at China Academy of Art; participated in Zhejiang University campus peer counseling practice; designed and facilitated groups on nature, mindfulness, communication, time management and behavioral activation.'))+item(L('精神卫生机构见习与实习','Mental health observation & internship'),L('2020—2024年于杭州市第七人民医院心理咨询门诊见习；2022年于该院精神四科住院部实习。见习与实习经历不等同于独立执业时数。','Observed counseling outpatient practice at Hangzhou Seventh People’s Hospital, 2020–2024, and completed a psychiatric inpatient internship in 2022. Observation and internship experience are distinct from independent counseling hours.')))}${section('03 / TRAINING','专业受训','Professional training',item(L('系统学习与方法训练','Academic & method-based training'),L('接受心理咨询与治疗、团体心理咨询、格式塔、创伤与危机干预等课程训练；参与认知行为疗法（CBT）、正念认知治疗（MBCT）、自杀的合作式评估与管理（CAMS）、积极心理干预及三阶段助人技术等培训与实践学习。','Coursework in counseling and psychotherapy, group counseling, Gestalt approaches, trauma and crisis intervention; further training and practice in cognitive behavioral therapy (CBT), mindfulness-based cognitive therapy (MBCT), Collaborative Assessment and Management of Suicidality (CAMS), positive psychological interventions and three-stage helping skills.'))+item(L('森林疗愈师培养','Forest therapy training'),L('完成日本森林疗法协会森林疗愈师培养计划并取得证书。该证书为专项培训证书。','Completed the forest therapist training program of the Japan Forest Therapy Society and received a training certificate.'))+item(L('专业伦理与持续学习','Ethics & continuing education'),L('2026年8月完成上海市心理卫生学会相关伦理培训，以及中国心理学会临床心理学注册工作委员会专业伦理课程。动机式访谈培训（2026.09—11）与绘画心理技术培训（2026.09—2027.02）截至2026年10月进行中。','Completed ethics training in August 2026 with the Shanghai Mental Health Association and the Clinical Psychology Registration Work Committee of the Chinese Psychological Society. Motivational interviewing (Sep–Nov 2026) and drawing-based psychological techniques (Sep 2026–Feb 2027) are in progress as of October 2026.')))} `;
if(page==='counseling') body+=section('04 / COURSEWORK','专业课程与持续学习','Coursework & continuing learning','')+section('05 / GROUPS','团体辅导实践','Group facilitation','');
document.documentElement.lang=en?'en':'zh-CN';document.title=L('王宣懿','Xuanyi Wang')+' | '+L(names.find(n=>n[0]===page+'.html')?.[1]||'自然与情绪健康',names.find(n=>n[0]===page+'.html')?.[2]||'Nature & emotional health');
document.body.innerHTML=`<a class="skip" href="#main">${L('跳至正文','Skip to content')}</a><header class="nav"><a class="brand" href="index.html${en?'?lang=en':''}"><span class="brand-mark">W<span>✳</span></span><span>${L('王宣懿','Xuanyi Wang')}<small>NATURE & MIND</small></span></a><button class="menu-toggle" aria-expanded="false" aria-label="${L('展开导航','Open navigation')}">☰</button><nav aria-label="${L('主导航','Main navigation')}">${names.map(n=>`<a ${n[0]===(page==='home'?'index':page)+'.html'?'aria-current="page"':''} href="${n[0]}${en?'?lang=en':''}">${L(n[1],n[2])}</a>`).join('')}<a class="language" href="${location.pathname.split('/').pop()||'index.html'}${en?'':'?lang=en'}" lang="${en?'zh-CN':'en'}">${en?'中文':'EN'} ↗</a></nav></header><main id="main">${body}<section class="contact"><div><div class="eyebrow">LET’S CONNECT</div><h2>${L('让交流，自然发生。','Let a conversation begin.')}</h2><p>${L('欢迎就学术研究、教学交流或心理咨询联系我。','For research collaboration, teaching exchange or counseling inquiries.')}</p></div><a href="mailto:wangxyi@wmu.edu.cn">wangxyi@wmu.edu.cn ↗</a></section></main><footer><span>© 2026 ${L('王宣懿','Xuanyi Wang')}</span><span>${L('温州医科大学精神医学学院','School of Mental Health · Wenzhou Medical University')}</span><span>${L('艺术配图由 AI 生成','Artificial intelligence (AI)-generated artwork')}</span></footer>`;
const toggle=document.querySelector('.menu-toggle');toggle.onclick=()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));document.querySelector('.nav').classList.toggle('open',!open)};
if(document.querySelector('#publications')) fetch('publications.json').then(r=>r.json()).then(ps=>{const el=document.querySelector('#publications');ps=ps.map((p,i)=>({...p,i}));if(el.dataset.selected)ps=ps.filter(p=>[0,1,3,5].includes(p.i));else ps.sort((a,b)=>(+(b.text.match(/\((20\d\d)\)/)||[])[1]||0)-(+(a.text.match(/\((20\d\d)\)/)||[])[1]||0));el.innerHTML=ps.map((p,i)=>`<article class="publication"><span class="pub-number">${String(i+1).padStart(2,'0')}</span><div><p>${p.text}</p><a href="${p.url}" target="_blank" rel="noopener noreferrer">${L('阅读论文','Read paper')} ↗</a></div></article>`).join('')}).catch(()=>{document.querySelector('#publications').textContent=L('论文列表暂时无法加载，请刷新重试。','Publications could not load. Please refresh.')});
